insert into public.products(id,slug,sku,legacy_sku,cat,status,featured,name,story,material,size,mode,sale,price,lead,care,images,pkg,catalogue,sort) values ('p18','ecoprint-sneakers-umber','NE-FTW-SNK-001',null,'footwear','published',false,'{"en":"Ecoprint Runner Sneakers","id":"Sneakers Runner Ecoprint"}'::jsonb,'{"en":"Versatile runner sneakers in premium canvas mixed with durable leather accents and umber leaf prints. The anti-slip rubber outsole keeps them comfortable and stable for daily wear. Available in a wide selection of models.","id":"Sneakers runner serbaguna dari kanvas premium dengan aksen kulit yang awet dan motif daun warna umber. Sol karet anti-slip membuatnya nyaman dan stabil untuk dipakai sehari-hari. Tersedia dalam banyak model."}'::jsonb,'{"en":"Premium canvas with leather accents; anti-slip rubber outsole","id":"Kanvas premium dengan aksen kulit; sol karet anti-slip"}'::jsonb,'{"en":"EU 37–43","id":"EU 37–43"}'::jsonb,'pattern','mto',975000,null,'textile','["sneakers-canvas","sneakers-brown"]'::jsonb,'{"w":1000,"dim":"33×22×12 cm"}'::jsonb,true,17) on conflict (id) do nothing;
