insert into public.products(id,slug,sku,legacy_sku,cat,status,featured,name,story,material,size,mode,sale,price,lead,care,images,pkg,catalogue,sort) values ('p21','ecoprint-fabric-collection','NE-FAB-MIX-001','NE-FAB-EC-001','fabric','published',false,'{"en":"Ecoprint Fabric Collection","id":"Koleksi Kain Ecoprint"}'::jsonb,'{"en":"An exclusive fabric collection in soft rayon, luxurious silk and comfortable cotton, each length hand-printed with natural dyes. Every piece is one of a kind, with botanical patterns transferred directly onto the textile. Tell us the base fabric, colour family and length you need.","id":"Koleksi kain eksklusif dari rayon lembut, sutra mewah dan katun yang nyaman, setiap potong dicetak tangan dengan pewarna alami. Setiap kain unik, dengan motif botanical yang berpindah langsung ke tekstil. Sebutkan bahan dasar, nuansa warna dan panjang yang Anda butuhkan."}'::jsonb,'{"en":"Rayon, silk or cotton; natural dyes","id":"Rayon, sutra atau katun; pewarna alami"}'::jsonb,'{"en":"Width and length per piece to be confirmed","id":"Lebar dan panjang per potong menunggu konfirmasi"}'::jsonb,'pattern','quote',null,null,'textile','["fabric-rack"]'::jsonb,'{"w":400,"dim":"30×25×4 cm"}'::jsonb,true,19) on conflict (id) do nothing;
