insert into public.products(id,slug,sku,legacy_sku,cat,status,featured,name,story,material,size,mode,sale,price,lead,care,images,pkg,catalogue,sort) values ('p22','womens-leather-flats-rose','NE-FTW-FS-002',null,'footwear','published',false,'{"en":"Women''s Ecoprint Leather Flats · Rose & Moss","id":"Sepatu Flat Kulit Wanita Ecoprint · Rose & Moss"}'::jsonb,'{"en":"Handcrafted women''s flats in genuine leather with a botanical ecoprint finish. Designed for all-day wear with a cushioned, anti-slip rubber outsole. This model: a pointed slip-on with a bow, printed in moss-green and rose leaves over a deep red ground.","id":"Sepatu flat wanita buatan tangan dari kulit asli dengan motif ecoprint botanical. Nyaman dipakai seharian dengan sol karet empuk dan anti-slip. Model ini: slip-on ujung lancip dengan pita, motif daun hijau lumut dan merah muda di atas dasar merah tua."}'::jsonb,'{"en":"Genuine leather upper; cushioned anti-slip rubber outsole","id":"Kulit asli; sol karet empuk anti-slip"}'::jsonb,'{"en":"EU 37–41","id":"EU 37–41"}'::jsonb,'pattern','mto',895000,'{"en":"Example: 21 working days from payment","id":"Contoh: 21 hari kerja sejak pembayaran"}'::jsonb,'leather','["flats-rose"]'::jsonb,'{"w":900,"dim":"32×20×12 cm"}'::jsonb,true,20) on conflict (id) do nothing;
